import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const d=JSON.parse('{"title":"罗伯托·戈伊苏埃塔","description":"","frontmatter":{"title":"罗伯托·戈伊苏埃塔","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/罗伯托·戈伊苏埃塔.md","filePath":"04_people/罗伯托·戈伊苏埃塔.md"}'),l={name:"04_people/罗伯托·戈伊苏埃塔.md"};function i(s,e,n,_,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="罗伯托·戈伊苏埃塔-roberto-goizueta" tabindex="-1">罗伯托·戈伊苏埃塔（Roberto Goizueta） <a class="header-anchor" href="#罗伯托·戈伊苏埃塔-roberto-goizueta" aria-label="Permalink to &quot;罗伯托·戈伊苏埃塔（Roberto Goizueta）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：可口可乐公司CEO（1981–1997）</li><li><strong>与巴菲特关系</strong>：在戈伊苏埃塔任内，伯克希尔成为可口可乐最大股东之一</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>罗伯托·戈伊苏埃塔是可口可乐公司历史上最伟大的CEO之一，也是20世纪最具影响力的商业领袖之一。1981年，他出任可口可乐CEO时，公司正面临增长停滞的困境。戈伊苏埃塔果断实施改革，将可口可乐从一家传统饮料公司转型为全球化的饮料帝国。在他的领导下，可口可乐大举开拓国际市场，将可乐文化推广至全球每一个角落。戈伊苏埃塔提出了著名的&quot;本土化思维，本土化行动&quot;战略，让可口可乐在世界各地扎根。1988年，巴菲特在戈伊苏埃塔的信任基础上，开始大举买入可口可乐股票，最终成为可口可乐最大的单一股东。戈伊苏埃塔以战略远见和卓越领导力，创造了可口可乐的黄金时代，被视为将可口可乐带入现代跨国企业时代的划时代人物。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1981年</strong>：出任可口可乐CEO，开启公司复兴之路</li><li><strong>1985年</strong>：推出&quot;新可乐&quot;（New Coke），虽然市场反应不佳，但展示了公司改革勇气</li><li><strong>1988年</strong>：巴菲特开始建仓可口可乐，戈伊苏埃塔与巴菲特建立起深厚信任</li><li><strong>1997年</strong>：戈伊苏埃塔因肺癌去世，任内将可口可乐市值从40亿美元提升至1800亿美元</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=罗伯托·戈伊苏埃塔在1997年股东信中的原话">1997年：完整翻译|/01_letters/1997年/翻译</a></li><li><a href="/search.html?q=罗伯托·戈伊苏埃塔在1993年股东信中的原话">1993年：完整翻译|/01_letters/1993年/翻译</a></li><li><a href="/search.html?q=罗伯托·戈伊苏埃塔在1996年股东信中的原话">1996年：完整翻译|/01_letters/1996年/翻译</a></li></ul>',11)])])}const p=t(l,[["render",i]]);export{d as __pageData,p as default};
